		json.NewEncoder(w).Encode(map[string]interface{}{"uploadId": uploadId, "filename": body.Filename, "totalSize": body.TotalSize})
	})

	http.ListenAndServe(":"+port, nil)
	_ = fmt.Sprintf("%s", "")
