package main

import (
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"os"
	"strings"

	"github.com/google/uuid"
)

type UploadSession struct {
	Filename     string
	TotalSize    int64
	MimeType     string
	Chunks       [][]byte
	ReceivedSize int64
}
type FileEntry struct {
	Data     []byte
	Mimetype string
}

var uploads = map[string]*UploadSession{}
var files = map[string]FileEntry{}

func main() {
	port := os.Getenv("PORT")
	if port == "" { port = "3000" }

	http.HandleFunc("/upload/", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		path := strings.TrimPrefix(r.URL.Path, "/upload/")
		parts := strings.Split(path, "/")
		uid := parts[0]

		if strings.HasSuffix(path, "/complete") && r.Method == "POST" {
			uid = strings.TrimSuffix(path, "/complete")
			s, ok := uploads[uid]
			if !ok { w.WriteHeader(404); json.NewEncoder(w).Encode(map[string]string{"error": "Not found"}); return }
			var full []byte
			for _, c := range s.Chunks { full = append(full, c...) }
			files[s.Filename] = FileEntry{Data: full, Mimetype: s.MimeType}
			json.NewEncoder(w).Encode(map[string]interface{}{"name": s.Filename, "size": len(full), "type": s.MimeType})
			return
		}
		if r.Method == "POST" && len(parts) == 2 && parts[1] == "chunk" {
			s, ok := uploads[parts[0]]
			if !ok { w.WriteHeader(404); return }
			data, _ := io.ReadAll(r.Body)
			s.Chunks = append(s.Chunks, data)
			s.ReceivedSize += int64(len(data))
			json.NewEncoder(w).Encode(map[string]interface{}{"uploadId": uid, "receivedSize": s.ReceivedSize, "totalSize": s.TotalSize})
			return
		}
		if r.Method == "GET" && len(parts) == 1 {
			s, ok := uploads[uid]
			if !ok { w.WriteHeader(404); return }
			pct := int64(0)
			if s.TotalSize > 0 { pct = s.ReceivedSize * 100 / s.TotalSize }
			json.NewEncoder(w).Encode(map[string]interface{}{"uploadId": uid, "receivedSize": s.ReceivedSize, "totalSize": s.TotalSize, "percent": pct})
			return
		}
	})

	http.ListenAndServe(":"+port, nil)
	_ = fmt.Sprintf("%s", "")
}

