from fastapi import FastAPI, UploadFile, File
from fastapi.responses import Response
from uuid import uuid4
import os
app = FastAPI()
port = int(os.getenv('PORT', 3000))
uploads = {}
files = {}
@app.post('/upload/init', status_code=201)
def init(body: dict):
    uid = str(uuid4())
    uploads[uid] = {'filename': body['filename'], 'totalSize': body['totalSize'], 'mimeType': body.get('mimeType', 'application/octet-stream'), 'chunks': [], 'receivedSize': 0}
    return {'uploadId': uid, 'filename': body['filename'], 'totalSize': body['totalSize']}
@app.post('/upload/{uid}/chunk')
async def upload_chunk(uid: str, file: UploadFile = File(...)):
    s = uploads.get(uid)
    if not s: return {'error': 'Not found'}, 404
    data = await file.read()
    s['chunks'].append(data); s['receivedSize'] += len(data)
    return {'uploadId': uid, 'receivedSize': s['receivedSize'], 'totalSize': s['totalSize']}
@app.get('/upload/{uid}')
def progress(uid: str):
    s = uploads.get(uid)
    if not s: return {'error': 'Not found'}, 404
    return {'uploadId': uid, 'receivedSize': s['receivedSize'], 'totalSize': s['totalSize'], 'percent': int(s['receivedSize'] / s['totalSize'] * 100)}
@app.post('/upload/{uid}/complete')
def complete(uid: str):
    s = uploads.get(uid)
    if not s: return {'error': 'Not found'}, 404
    full = b''.join(s['chunks'])
    files[s['filename']] = {'data': full, 'mimetype': s['mimeType']}
    return {'name': s['filename'], 'size': len(full), 'type': s['mimeType']}
@app.get('/files/{name}')
def get_file(name: str):
    f = files.get(name)
    if not f: return Response(status_code=404)
    return Response(content=f['data'], media_type=f['mimetype'])

